import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = next(iterator)
            B = next(iterator)
        except StopIteration:
            break

        alice_stones = sorted(list(A))
        bob_stones = sorted(list(B), reverse=True)

        alice_queue = deque(alice_stones)
        bob_queue = deque(bob_stones)

        S = [''] * (2 * N)

        left_ptr = 0
        right_ptr = 2 * N - 1
        turn = 0

        for _ in range(2 * N):
            if turn % 2 == 0:
                char = alice_queue.popleft()
                if turn < N:
                    S[left_ptr] = char
                    left_ptr += 1
                else:
                    S[right_ptr] = char
                    right_ptr -= 1
            else:
                char = bob_queue.popleft()
                if turn < N:
                    S[right_ptr] = char
                    right_ptr -= 2
                else:
                    S[left_ptr] = char
                    left_ptr += 2

            turn += 1

        results.append("".join(S))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
